def main():
    here = os.path.dirname(os.path.abspath(__file__))
    table = {row[0]: row[1:] for row in T}
    missing_total = 0
    for i, lang in enumerate(LANGS):
        path = os.path.join(here, f"shellwarden_{lang}.ts")
        tree = ET.parse(path)
        root = tree.getroot()
        root.set("language", {"uk": "uk_UA", "ru": "ru_RU", "fr": "fr_FR", "es": "es_ES"}[lang])
        missing = []
        for msg in root.iter("message"):
            src = msg.find("source").text
            tr = msg.find("translation")
            if msg.get("numerus") == "yes" and src in N:
                for f in list(tr):
                    tr.remove(f)
                tr.text = None
                for form in N[src][i]:
                    ET.SubElement(tr, "numerusform").text = form
                tr.attrib.pop("type", None)
            elif src in table:
                tr.text = table[src][i]
                tr.attrib.pop("type", None)
            else:
                tr.set("type", "unfinished")
                missing.append(src)
        tree.write(path, encoding="utf-8", xml_declaration=True)
        # lupdate writes the doctype; keep the file Qt Linguist-friendly
        with open(path, encoding="utf-8") as f:
            text = f.read()
        if "<!DOCTYPE TS>" not in text:
            text = text.replace("?>", "?>\n<!DOCTYPE TS>", 1)
            with open(path, "w", encoding="utf-8") as f:
                f.write(text)
        missing_total += len(set(missing))
        print(f"{lang}: {len(set(missing))} untranslated")
        for m in sorted(set(missing)):
            print("   -", repr(m))
    return 1 if missing_total else 0


if __name__ == "__main__":
    sys.exit(main())
